<div class="page-head"><div><h1><?= e($p['code']) ?> — <?= e($p['title']) ?></h1><p class="sub"><?= e(t('enum.pcat.' . $p['category'])) ?><?= $p['doc_level'] ? ' · ' . e(t('enum.doclevel.' . $p['doc_level'])) : '' ?> · <?= cls_badge($p['classification']) ?> · <?= e($p['owner_name']) ?> · <?= status_badge($p['status']) ?> · <?= e(t('pol.next_review')) ?>: <?= e(fdate($p['next_review_date']) ?: '—') ?></p></div>
<div class="actions"><a class="btn secondary" href="<?= e(url('policies/framework')) ?>"><?= icon('layers') ?> <?= e(t('docs.framework')) ?></a><a class="btn secondary" href="<?= e(url('policies')) ?>"><?= e(t('common.back')) ?></a><?php if (can('policy.manage')): ?><a class="btn" href="<?= e(url('policies/' . $p['id'] . '/edit')) ?>"><?= e(t('common.edit')) ?></a><?php endif; ?></div></div>
<section class="card"><h2><?= e(t('docs.control')) ?></h2><dl class="details">
<dt><?= e(t('docs.code')) ?></dt><dd dir="ltr" class="code"><?= e($p['code']) ?></dd>
<?php if ($p['title_en']): ?><dt><?= e(t('docs.title_en')) ?></dt><dd dir="ltr"><?= e($p['title_en']) ?></dd><?php endif; ?>
<dt><?= e(t('docs.level')) ?></dt><dd><?= e($p['doc_level'] ? t('enum.doclevel.' . $p['doc_level']) : '—') ?></dd>
<dt><?= e(t('docs.section')) ?></dt><dd><?= e($p['rm_section'] ? t('enum.rmsec.' . $p['rm_section']) : '—') ?></dd>
<dt><?= e(t('docs.approval_body')) ?></dt><dd><?= e($p['approval_body'] ?? '—') ?></dd>
<dt><?= e(t('docs.parent')) ?></dt><dd><?php if ($parent): ?><a href="<?= e(url('policies/' . $parent['id'])) ?>"><?= e($parent['code'] . ' — ' . $parent['title']) ?></a><?php elseif ($p['parent_code']): ?><span class="code" dir="ltr"><?= e($p['parent_code']) ?></span> <span class="badge warn"><?= e(t('docs.not_registered')) ?></span><?php else: ?>—<?php endif; ?></dd>
<?php if ($children): ?><dt><?= e(t('docs.children')) ?></dt><dd><?php foreach ($children as $c): ?><a href="<?= e(url('policies/' . $c['id'])) ?>"><?= e($c['code']) ?></a> <?= e($c['title']) ?><br><?php endforeach; ?></dd><?php endif; ?>
<?php if ($refs): ?><dt><?= e(t('docs.refs')) ?></dt><dd><?php foreach ($refs as $code => $r): ?><?php if ($r): ?><a href="<?= e(url('policies/' . $r['id'])) ?>" dir="ltr"><?= e($code) ?></a><?php else: ?><span class="code" dir="ltr"><?= e($code) ?></span> <span class="badge warn"><?= e(t('docs.not_registered')) ?></span><?php endif; ?><br><?php endforeach; ?></dd><?php endif; ?>
<?php if ($citedBy): ?><dt><?= e(t('docs.cited_by')) ?></dt><dd><?php foreach ($citedBy as $c): ?><a href="<?= e(url('policies/' . $c['id'])) ?>" dir="ltr"><?= e($c['code']) ?></a> <?php endforeach; ?></dd><?php endif; ?>
<?php if ($p['kb_source_id'] && can('ai.use')): ?><dt><?= e(t('ai.library')) ?></dt><dd><a href="<?= e(url('assistant/library/' . $p['kb_source_id'])) ?>"><?= icon('book') ?> <?= e(t('docs.in_library')) ?></a></dd><?php endif; ?>
</dl><?php if (!$filesOk): ?><p class="muted small"><?= icon('lock') ?> <?= e(t('docs.files_restricted')) ?></p><?php endif; ?></section>
<section class="card" id="versions"><h2><?= e(t('pol.versions')) ?></h2>
<?php if (!$versions): ?><p class="muted"><?= e(t('pol.no_versions')) ?></p><?php endif; ?>
<?php foreach ($versions as $v): ?><div class="card" style="margin-bottom:8px"><h3><?= e($v['version_label']) ?> <?= $v['is_current'] ? '<span class="badge ok">' . e(t('pol.current')) . '</span>' : '<span class="badge">' . e(t('pol.superseded')) . '</span>' ?><?= ($v['status'] ?? 'approved') === 'pending' ? ' <span class="badge warn">' . e(t('pol.pending_approval')) . '</span>' : '' ?><?= ($v['status'] ?? 'approved') === 'rejected' ? ' <span class="badge danger">' . e(t('enum.astatus.rejected')) . '</span>' : '' ?></h3>
<dl class="details"><dt><?= e(t('pol.effective_date')) ?></dt><dd><?= e($v['effective_date']) ?></dd><dt><?= e(t('pol.approved_by')) ?></dt><dd><?= e($v['approved_by'] ?? '—') ?> <?= e(fdate($v['approval_date'])) ?></dd><dt><?= e(t('pol.change_summary')) ?></dt><dd class="pre"><?= e($v['change_summary'] ?? '—') ?></dd><dt><?= e(t('audit.user')) ?></dt><dd><?= e($v['full_name']) ?> · <?= e(fdatetime($v['created_at'])) ?></dd>
<dt><?= e(t('upload.title')) ?></dt><dd><?php foreach ($atts[$v['id']] ?? [] as $a): ?><a href="<?= e(url('attachments/' . $a['id'])) ?>"><?= e($a['original_name']) ?></a> <?php if (can('policy.manage')): ?><form method="post" class="inline" action="<?= e(url('attachments/' . $a['id'] . '/delete')) ?>" data-confirm="<?= e(t('upload.confirm_delete')) ?>"><?= csrf_field() ?><button class="btn small danger" type="submit"><?= e(t('common.delete')) ?></button></form><?php endif; ?><br><?php endforeach; ?><?= empty($atts[$v['id']]) ? '—' : '' ?>
<?php if (can('policy.manage') && $filesOk): ?><form method="post" enctype="multipart/form-data" action="<?= e(url('policies/' . $p['id'] . '/versions/' . $v['id'] . '/attachments')) ?>"><?= csrf_field() ?><input type="file" name="file" required accept=".pdf,.png,.jpg,.jpeg,.txt,.docx,.xlsx" aria-label="<?= e(t('upload.choose')) ?>"> <button class="btn small secondary" type="submit"><?= e(t('upload.submit')) ?></button></form><?php endif; ?></dd></dl></div><?php endforeach; ?>
<?php if (can('policy.manage')): ?><details><summary><strong><?= e(t('pol.add_version')) ?></strong></summary><p class="muted"><?= e(t('pol.version_note')) ?></p>
<form method="post" enctype="multipart/form-data" action="<?= e(url('policies/' . $p['id'] . '/versions')) ?>" class="form-grid" novalidate><?= csrf_field() ?>
<?= ff('text', 'version_label', 'pol.version', '', ['required' => true]) ?><?= ff('date', 'effective_date', 'pol.effective_date', date('Y-m-d'), ['required' => true]) ?>
<?= ff('text', 'approved_by', 'pol.approved_by', '', ['hint' => t('pol.approved_hint')]) ?><?= ff('date', 'approval_date', 'pol.approval_date', '') ?>
<?= ff('textarea', 'change_summary', 'pol.change_summary', '', ['wide' => true]) ?>
<div class="field wide<?= field_error('file') ? ' has-error' : '' ?>"><label for="pfile"><?= e(t('upload.choose')) ?></label><input type="file" id="pfile" name="file" accept=".pdf,.png,.jpg,.jpeg,.txt,.docx,.xlsx"><?= field_error('file') ?></div>
<div class="field wide"><label class="check"><input type="checkbox" name="needs_approval" value="1"> <?= e(t('pol.needs_approval')) ?></label><p class="hint"><?= e(t('pol.needs_approval_hint')) ?></p></div>
<div class="field"><button class="btn" type="submit"><?= e(t('pol.add_version')) ?></button></div></form></details><?php endif; ?></section>
